window.MONSTER_CHUNK_43 = [{"name":"Globster","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"ooze","subtypes":["aquatic"],"init":-5,"auras":["stench (DC 18, 10 rounds)"],"ac":16,"ac_touch":4,"ac_flat_footed":16,"ac_mods":"-5 Dex, +12 natural, -1 size","hp":57,"hd":"6d8+30","hdvalue":6,"fort":7,"ref":-3,"will":-3,"immunities":["acid","bludgeoning and piercing damage","ooze traits"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"speed":[{"type":"land","speed":20},{"type":"swim","speed":40}],"melee":"slam +9 (2d6+9 plus grab and nausea)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"constrict","details":"2d6+9"}],"strength":22,"dexterity":1,"constitution":20,"wisdom":1,"charisma":1,"baseatk":4,"cmb":11,"cmb_special":"+4 vs. grapple","cmd":16,"cmd_special":"can't be tripped","skills":[{"skill":"Swim","value":14}],"sq":[{"type":"decompose"},{"type":"water dependency"}],"environments":["any coastlines","any oceans"],"organizations":["solitary","pair","beaching (3-8)"],"treasure":"none","description_visual":"This grotesque mass of blubber and rancid flesh piles up hideously upon itself, opening a vast maw filled with teeth.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Create Spawn","kind":"Ex","details":"When a globster eats a living creature, it only digests a small portion of the remains. As the undigested remains accumulate inside of it, the globster grows more and more bloated. As a full-round action that doesn't provoke attacks of opportunity, a globster can regurgitate these foul remains along with portions of its own mass. Doing so causes the globster 1d6 points of damage, but creates a new, fully grown globster that immediately attacks the nearest non-globster target. A globster can create spawn up to once per day, though only after it has fed upon at least four Medium-sized creatures (or the equivalent number of creatures of other sizes)."},{"type":"Decompose","kind":"Ex","details":"A slain globster decays into a mass of goo in the span of 24 hours. However, the corpse retains the creature's stench aura for 1d10 days after its death."},{"type":"Nausea","kind":"Ex","details":"Any creature struck by a globster must make a DC 18 Fortitude save to avoid being nauseated for 1 round. Once a creature makes this saving throw, it is immune to further nausea effects from that particular globster for 24 hours. This is a poison effect. The save DC is Constitution-based."}],"description":"A globster is a living collection of half-digested parts from large sea creatures such as whales and squid. Passersby usually discover it by smell long before they see it. Many unfortunate folk who happen upon a globster mistake it for the carcass of a beached sea animal, getting too close before discovering the seemingly dead creature is very much alive. For a time, sages believed globsters were undead-that they were simply undulating wads of rotting flesh animated with a drive to feed. However, globsters are actually living creatures.\n\nGlobsters usually wash up on a beach or float to the shore to feed on terrestrial stock for a few hours before returning to the safety of water. Some say the tides and phases of the moon are to blame for the times globsters come to land to feed. Globsters reproduce by mixing parts of their own foul bodies with the poorly digested remains of their meals.","ecology":"","habitat_society":""},{"name":"Graeae","cr":5,"xp":1600,"alignment":"NE","size":"Medium","type":"monstrous humanoid","subtypes":["evil","mythic"],"init":3,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":65,"hd":"6d10+32","hdvalue":6,"fort":3,"ref":8,"will":8,"dr":"5/epic","sr":16,"weaknesses":["eye of the graeae"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"2 claw +8 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"luck ripple"},{"type":"mythic power","details":"2/day, surge +1d6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"arcane sight"},{"spell":"fly"},{"spell":"undetectable alignment"}]},{"frequency":"1/day","spells":[{"spell":"ray of exhaustion"}]},{"frequency":"3/day","spells":[{"spell":"augury"},{"spell":"enthrall"},{"spell":"feast of ashes"}]},{"frequency":"5/day","spells":[{"spell":"ill omen"}]}],"strength":14,"dexterity":17,"constitution":12,"intelligence":23,"wisdom":13,"charisma":8,"baseatk":6,"cmb":8,"cmd":21,"feats":[{"feat":"Combat Casting"},{"feat":"Iron Will","type":"mythic"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":5},{"skill":"Craft (alchemy)","value":15},{"skill":"Fly","value":15},{"skill":"Intimidate","value":8},{"skill":"Knowledge (arcana)","value":12},{"skill":"Perception","value":10},{"skill":"Spellcraft","value":12},{"skill":"Stealth","value":12},{"skill":"Survival","value":10},{"skill":"Use Magic Device","value":5}],"languages":["Aklo","Common","Giant","Goblin","Sylvan"],"sq":[{"type":"coven"},{"type":"fate casting"}],"environments":["any"],"organizations":["solitary","a pair","coven (3-12)"],"treasure":"standard","description_visual":"Haggard and hunched, this blind and snaggletoothed crone guides herself by a gruesomely bloated eyeball she clutches in her claws.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Coven","kind":"Ex","details":"Like hags, graeaes also form covens. A graeae coven can be composed entirely of graeaes, or could or include hags or witches with the coven hex. A hag or witch with the coven hex counts as a graeae for purposes of joining a graeae's coven. Likewise, a graeae counts as a hag for purposes of joining a hag's coven."},{"type":"Eye of the Graeae","kind":"Su","details":"Each graeae possesses a mystic eyeball. A graeae can sense the location of her eyeball from anywhere on the same plane. She must remain within 30 ft. of her eyeball or she becomes completely blind and cannot use any of her spell-like or supernatural abilities. The eyeball only works for its graeae. If a graeae is slain, her mystic eye instantly turns to dust."},{"type":"Fate Casting","kind":"Su","details":"A graeae has the ability to predict future events. On a creature's request, a graeae can expend a use of mythic power as a full-round action to answer a single question as if by the divination spell."},{"type":"Luck Ripple","kind":"Su","details":"A graeae can use her mystic eye to alter the circumstances of any creature within 30 ft. As a swift action, she can cast her eye on a single creature, causing the target to take a -2 penalty or gain a +2 bonus to one of the following (graeae's choice): AC, ability checks, attack rolls, saving throws, or skill checks. A successful DC 19 Will save negates the effect, which otherwise lasts for 1d6 rounds. This is a mind-affecting gaze effect. The DC of the save is Intelligence-based."}],"description":"A graeae is a haglike creature, though more human in appearance. Some describe them as emissaries of the gods, while others believe graeaes to be physical manifestations of fate.\n\nGRAEAE COVEN\n\nWhenever three or more graeaes of the same coven are within 10 ft. of one another, they can work together to use any of the following spell-like abilities: clairaudience/clairvoyance, commune, contact other plane, speak with dead, and tongues. All three graeaes must spend a full-round action to take part in this form of cooperative magic. All coven spell-like abilities are CL 9th (or at the highest caster level available to the most powerful graeaes in the coven).","ecology":"","habitat_society":""},{"name":"Graven Guardian","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"construct","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+2 Dex, +8 natural","hp":53,"hd":"6d10+20","hdvalue":6,"hp_mods":["fast healing 2"],"fort":2,"ref":4,"will":3,"dr":"5/adamantine","immunities":["construct traits"],"sr":16,"weaknesses":["faith bound"],"speed":[{"type":"land","speed":40}],"melee":"+1 keen scimitar +10 (1d6+5/15-20 plus bleed) or slam +9 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"2"},{"type":"magic weapon"},{"type":"rest eternal"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"haste","details":"self only"}]}],"strength":16,"dexterity":15,"wisdom":12,"charisma":1,"baseatk":6,"cmb":9,"cmd":21,"sq":[{"type":"guardian domains","details":"Death, Repose"}],"environments":["any land"],"organizations":["solitary","band (2-4)","assembly (5-12)"],"treasure":"incidental (masterwork scimitar)","description_visual":"This jackal-headed, brightly painted clay statue animates and lurches forward, hefting a wickedly hooked sword.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Faith Bound","kind":"Su","details":"A graven guardian cannot attack any creature that openly wears or displays the holy or unholy symbol of the deity to which the graven guardian is dedicated unless that creature first attacks the graven guardian."},{"type":"Magic Weapon","kind":"Su","details":"A graven guardian that carries its deity's favored weapon treats that weapon as a +1 weapon as long as it is wielded by the guardian. If the weapon is a melee weapon, it gains the keen weapon special ability (even if the weapon is a bludgeoning weapon). If it is a thrown weapon, it gains the returning weapon special ability. If it is a ranged weapon, it gains the seeking weapon special ability, and generates new ammunition with each attack (this ammunition is destroyed whether or not it hits)."}],"description":"Graven guardians are human-sized constructs of clay, stone, wood, or similar materials, crafted and painted to resemble a deity or a deity's favored servants. When not in motion, a graven guardian appears identical to a temple or crypt's statue, but while active, graven guardians look extremely lifelike.\n\nGraven guardians are inexorably tied to a specific deity's faith. While unintelligent and thus lacking any\n\nreal personality, a graven guardian has the ability to recognize fellow worshipers or minions of its deity and doesn't treat them as enemies unless they first attack. This recognition doesn't extend so far as to allow these worshipers (or those cunningly disguised as worshipers) to give a graven guardian new orders. As with all constructs, a graven guardian follows only the orders of its creator.\n\nGUARDIAN DOMAINS\n\nEach graven guardian gains a special ability from two domains assigned during construction. Save DCs for these abilities are Wisdom-based (DC 14 for most guardians). Caster level for these abilities is equal to the graven guardian's Hit Dice (CL 6th for most graven guardians).\n\nAir: Flight (Su)-The graven guardian gains a fly speed equal to its base speed with average maneuverability and a Fly skill of +6 (this includes a +4 racial bonus).\n\nAnimal: Beast Ward (Su)-Animals must make a Will save before they can attack the graven guardian. Any attack on an animal (but not its allies) by the graven guardian breaks this protection. Once the animal makes this Will save, it need not save again against that particular graven guardian on subsequent attacks.\n\nArtifice: Repair (Ex)-The graven guardian's fast healing increases to 5.\n\nChaos: Chaotic Weapons (Su)-The graven guardian's weapon and slam attacks are treated as chaotic-aligned. Its magic weapon deals +1d6 points of damage to lawful targets.\n\nCharm: Command (Su)-The graven guardian can cast command three times per day as a spell-like ability.\n\nCommunity: Alliance (Su)-Adjacent worshipers and graven guardians dedicated to the same god gain a +1 luck bonus on attack rolls, weapon damage rolls, and saves.\n\nDarkness: Darkness (Su)-The graven guardian can cast darkness two times per day as a spell-like ability.\n\nDeath: Bleed (Ex)-The graven guardian's weapon deals 2 points of bleed damage on a hit.\n\nDestruction: Shatter (Ex)-The graven guardian can cast shatter two times per day as a spell-like ability.\n\nEarth: Rocky (Ex)-The graven guardian's natural armor bonus increases by +2.\n\nEvil: Evil Weapons (Su)-The graven guardian's weapon and slam attacks are treated as evil-aligned. Its magic weapon deals +1d6 points of damage to good targets.\n\nFire: Flaming (Su)-The graven guardian's weapon gains the flaming property.\n\nGlory: Glorious (Su)-The graven guardian's magic weapon and slam attack deal an additional 1d6 points of damage against undead creatures.\n\nGood: Good Weapons (Su)-The graven guardian's weapon and slam attacks are treated as good-aligned. Its magic weapon deals +1d6 points of damage to evil targets\n\nHealing: Recovery (Su)-Once per day, when reduced below half hit points, the graven guardian automatically heals 3d10+6 points of damage.\n\nKnowledge: Familiarity (Su)-The graven guardian gains a +2 bonus on attack rolls again any creature it attacked in the past round.\n\nLaw: Lawful Weapons (Su)-The graven guardian's weapons and slam attacks are treated as lawful-aligned. Its magic weapon deals +1d6 points of damage to chaotic targets.\n\nLiberation: Unfettered (Su)-The graven guardian gains a +4 bonus to its CMD.\n\nLuck: Lucky (Su)-Once per day, the graven guardian may roll a saving throw twice and take the better of the two results as the actual result.\n\nMadness: Confusion (Su)-The graven guardian can cast confusion once per day as a spell-like ability.\n\nMagic: Resistant (Su)-The graven guardian's SR increases by 5.\n\nNobility: Honored (Su)-The graven guardian gains a +1 bonus on attack rolls and combat maneuver checks.\n\nPlant: Entangle (Su)-The graven guardian can cast entangle three times per day as a spell-like ability.\n\nProtection: Protected (Su)-The graven guardian gains a +2 bonus on all saves.\n\nRepose: Rest Eternal (Su)- Damage dealt by the graven guardian resists any magical healing. Attempting to use magical healing to cure this damage requires a successful caster level check against the guardian's SR. This ability doesn't affect natural healing or healing provided by extraordinary abilities.\n\nRune: Rune Carved (Su)-Runes cover the graven guardian. Whenever the graven guardian takes energy damage or energy damage fails to overcome its SR, for the next round, its attacks deal +1d6 points of damage of that energy type. If more than one type of energy attack occurs in a round, roll randomly to determine what kind of extra energy damage it deals.\n\nStrength: Powerful (Ex)-The graven guardian gains Power Attack as a bonus feat.\n\nSun: Dazzling (Su)-When the graven guardian scores a critical hit with its magic weapon, a bright flash blinds the target for 1d4 rounds (Fortitude save negates).\n\nTravel: Speedy (Su)-The guardian gains Mobility as a bonus feat, and all of its modes of movement increase by +10 ft.\n\nTrickery: Trip (Su)-The graven guardian gains the trip ability with its melee weapon and slam attacks.\n\nWar: Enhanced (Su)-The enhancement bonus of the graven guardian's weapon increases to +2.\n\nWater: Swimmer (Ex)-The guardian gains a swim speed equal to its base speed, and a Swim skill of +11.\n\nWeather: Shocking Weapon (Su)-The graven guardian's weapon gains the shock special ability.\n\nCONSTRUCTION\n\nA graven guardian's body must be sculpted from clay, stone, or wood, and adorned with precious stones, rare woods, or metal inlays worth 500 gp. The Hit Dice and size of graven guardians can be increased as though they were golems.\n\nGRAVEN GUARDIAN\n\nCL 7th; Price 18,500 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, greater magic weapon, haste, imbue with spell ability, make whole, stone shape, creator must be caster level 7th; Skill Craft (sculpture) or Craft (pottery) DC 15; Cost 9,500 gp","ecology":"","habitat_society":""},{"name":"Great Diadem Urchin","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"vermin","subtypes":["aquatic"],"init":-4,"senses":[{"type":"all-around vision"},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"30 ft."}],"ac":20,"ac_touch":6,"ac_flat_footed":20,"ac_mods":"-4 Dex, +14 natural","hp":57,"hd":"6d8+30","hdvalue":6,"hp_mods":["regeneration 3 (fire, acid)"],"fort":10,"ref":-2,"will":3,"defensive_abilities":["stability"],"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":10}],"melee":"3 spines +9 (1d8+5 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"spines"}],"strength":21,"dexterity":3,"constitution":20,"wisdom":13,"charisma":2,"baseatk":4,"cmb":9,"cmd":15,"cmd_special":"+8 vs. bull rush or trip","skills":[{"skill":"Perception","value":5}],"sq":[{"type":"amphibious"}],"environments":["temperate coastlines","temperate oceans","warm coastlines","warm oceans"],"organizations":["solitary","pair","cluster (2-5)"],"treasure":"none","description_visual":"Thick spines like the flanges of a royal crown bristle all across the surface of this strangely large golden sea urchin.","group":"Sea Urchin","source":"AP 56","special_abilities":[{"type":"Poison","kind":"Ex","details":"Spines-injury; save Fort DC 18; frequency 1/round for 6 rounds; effect 1d2 Con and stunned for 1 round; cure 1 save. Great diadem urchin venom is shockingly painful and feels acidic at the moment of contact-though the worst of the pain fades after a moment. The save DC is Constitution-based."},{"type":"Spines","kind":"Ex","details":"A great diadem urchin's spines can swivel to face any approaching creature. Any creature that attacks a great diadem urchin with an unarmed strike or a natural attack, or any Large or smaller creature that attacks with a one-handed weapon or light weapon, is automatically attacked by the hunter urchin's spines as an immediate action. If the spines hit, they can poison the target as well."}],"description":"Enormous and brilliantly colored diadem urchins are often sought after by terrestrial collectors or aquatic creatures seeking to simultaneously decorate and defend their throne rooms, yet such beasts are never truly trainable, and attack anyone who comes close.","ecology":"","habitat_society":""},{"name":"Green Hag","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"monstrous humanoid","init":1,"senses":[{"type":"darkvision","modifier":"90 ft."}],"ac":19,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+1 Dex, +8 natural","hp":58,"hd":"9d10+9","hdvalue":9,"fort":6,"ref":7,"will":7,"sr":16,"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"2 claws +13 (1d4+4 plus weakness)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"pass without trace"},{"spell":"tongues"},{"spell":"water breathing"}]},{"frequency":"at-will","spells":[{"spell":"alter self"},{"spell":"dancing lights"},{"spell":"ghost sound"},{"spell":"invisibility"},{"spell":"pyrotechnics"},{"spell":"tree shape"},{"spell":"whispering wind"}]}],"strength":19,"dexterity":12,"constitution":12,"intelligence":15,"wisdom":13,"charisma":14,"baseatk":9,"cmb":13,"cmd":24,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Deceitful"},{"feat":"Great Fortitude"}],"skills":[{"skill":"Bluff","value":13},{"skill":"Disguise","value":13},{"skill":"Knowledge (arcana)","value":11},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":9},{"skill":"Stealth","value":13},{"skill":"Swim","value":18}],"languages":["Aklo","Common","Giant"],"sq":[{"type":"mimicry"}],"environments":["temperate marshes"],"organizations":["solitary","coven (3 hags of any kind)"],"treasure":"standard","description_visual":"Knots of dark, moldering hair spill over the features of this sickly, thin, green-skinned crone.","group":"hag","source":"PFRPG Bestiary","special_abilities":[{"type":"Weakness","kind":"Su","details":"A green hag's claws sap strength from those she strikes. Each time a green hag hits a foe with her claw attack, the victim takes 2 points of Strength damage unless he resists the weakness with a DC 16 Fortitude save. Alternatively, a green hag can attempt to inflict even greater weakness on a foe by making a touch attack-this variant requires a standard action, and cannot be attempted in the same round the hag makes claw attacks. The opponent touched must succeed on a DC 16 Fortitude save or take 2d4 points of Strength damage. The save DC is Charisma-based."},{"type":"Mimicry","kind":"Ex","details":"A green hag can imitate the sounds of almost any animal found near its lair."}],"description":"Terrifying crones known to haunt foul swamps and tangled forests, green hags harbor an intense hatred for all beauty and purity. Making use of their varied deceptive abilities, these crones delight in murdering innocents, unhinging noble minds, and debasing the pure of heart. They are particularly fond of using disguise self to assume the forms of alluring young maidens and then seducing young men away from their lovers or families. In this form, they can infect such noble and upstanding citizens with all manner of debauchery and scandal. Some green hags prefer to reveal their true natures to their lovers at a moment precisely engineered to drive the man mad with horror and shame. Others drag out their dalliances and do what they can to utterly ruin the lives of the men they seduce before showing the broken shell that remains the truth. In the end, the luckiest of these unfortunate lovers end up being eaten by their green hag companions-for the unlucky, their final doom can be much worse, for the cruel imagination of the green hag is vast. A typical green hag stands between 5 and 6 ft. tall and weighs just under 160 pounds. Hag Covens When three hags of any type gather, they can form a coven to gain increased magical ability. Any combination of hags can form a coven, but green hags are the most common members of such foul gatherings. Whenever all three hags of a particular coven are within 10 ft. of one another, all three of them can work together to use any of the following spell-like abilities: animate dead, baleful polymorph (DC 18), blight (DC 17), bestow curse (DC 17), clairaudience/clairvoyance, charm monster (DC 17), commune, control weather, dream, forcecage, mind blank, mirage arcana (DC 18), reincarnate, speak with dead, veil (DC 19), vision. All three hags must take a fullround action to take part in this form of cooperative magic. All coven spell-like abilities function at CL 9th (or at the highest CL available to the most powerful hag in the coven). The save DCs are Charisma-based, and function as if with a Charisma score of 16 unless one of the hags has a higher Charisma score, in which case the spell-like ability DCs are adjusted by that hag's Charisma modifier. At the GM's discretion, certain more powerful hag covens might have additional spell-like abilities.","ecology":"","habitat_society":""},{"name":"Grodair","cr":5,"xp":1600,"alignment":"CN","size":"Medium","type":"magical beast","subtypes":["aquatic","extraplanar"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":16,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"-1 Dex, +7 natural","hp":66,"hd":"7d10+28","hdvalue":7,"fort":11,"ref":4,"will":5,"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"bite +11 (1d8+4), 2 tentacles +6 (1d4+2 plus trip)","ranged":"water blast +7 touch (1d8 plus push)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death flood"},{"type":"push","details":"water blast, 5 ft."}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"control water"}]}],"strength":18,"dexterity":8,"constitution":19,"intelligence":12,"wisdom":13,"charisma":15,"baseatk":7,"cmb":11,"cmd":20,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Weapon Focus (water blast)"}],"skills":[{"skill":"Knowledge (nature)","value":8},{"skill":"Survival","value":8},{"skill":"Swim","value":22}],"languages":["Aquan","Sylvan"],"sq":[{"type":"amphibious"},{"type":"muddy field"}],"environments":["any coastlines","any water"],"organizations":["solitary"],"treasure":"standard","description_visual":"Several water-dripping tentacles sprout from this four-eyed fish's belly, while long fins protrude from its back.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Death Flood","kind":"Su","details":"When a grodair is killed, it immediately explodes in a 15-foot-radius burst of highly pressurized water that deals 5d6 points of bludgeoning damage (Reflex DC 17 half). After the explosion, a successful DC 25 Survival check allows a creature to recover a cluster of strange organs from the remains. This cluster functions as a decanter of endless water for 2d6 hours, but can only produce a \"stream\" or \"fountain\" effect. Failing this Survival check by 5 or more causes the cluster to burst, dealing an additional 2d6 points of damage to that creature (no save) and destroying the organs entirely. The save DC is Constitution-based."},{"type":"Muddy Field","kind":"Su","details":"As a standard action when on sand, soil, or other types of loose earth, a grodair can gush standing water into the area surrounding it. Upon doing so, the land within 15 ft. of the grodair is treated as a shallow bog. This water remains as long as the grodair is within 15 ft. and wishes to maintain the water. The bog instantly disperses as soon as the grodair is killed or moves out of the area."},{"type":"Water Blast","kind":"Ex","details":"The grodair's ranged attack is a pressurized blast of water. This attack has a range of 60 ft. with no range increment."}],"description":"A grodair is a bloated aquatic creature from the primal world of the fey. The bulbous sac on its spine is an extradimensional space that can contain thousands of gallons of water. The creature drains water (including small bits of debris and even very small creatures) from one place and releases it in another, typically creating boggy areas as it moves so it can travel more quickly than its tentacles can carry it. A grodair can rise up to 6 ft. on its tentacles, measures 7 ft. long, and weighs about 400 pounds.\n\nA grodair is intelligent, but extremely absentminded and careless. Its memory is poor, and it has difficulty remembering things it was told even 5 minutes prior- though it can recall some events of the distant past with perfect (and often frustrating) clarity.","ecology":"","habitat_society":""},{"name":"Hieracosphinx","cr":5,"xp":1600,"alignment":"CE","size":"Large","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+2 Dex, +6 natural, -1 size","hp":60,"hd":"8d10+16","hdvalue":8,"fort":8,"ref":8,"will":4,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"bite +11 (1d10+4), 2 claws +11 (1d6+4)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"shriek"}],"strength":19,"dexterity":14,"constitution":15,"intelligence":6,"wisdom":15,"charisma":10,"baseatk":8,"cmb":13,"cmd":25,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Flyby Attack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":3},{"skill":"Perception","value":16}],"languages":["Sphinx"],"environments":["warm hills"],"organizations":["solitary","pair","flock (3-8)"],"treasure":"incidental","description_visual":"A cold-eyed falcon's head and great wings adorn the body of this otherwise leonine creature.","group":"Sphinx","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Shriek","kind":"Su","details":"The shrill shriek of a hieracosphinx deafens non-sphinxes within a 60-foot-radius spread for 2d4 rounds (DC 16 Fortitude negates). Once a creature successfully saves against this effect, it is immune to the hieracosphinx's shriek for 24 hours. Using this ability is a standard action. The save DC is Constitution-based."}],"description":"The least intelligent of the common sphinxes, hieracosphinxes are a cowardly, cruel-hearted lot. All are male. They despise the larger and cleverer androsphinxes and criosphinxes. Toward gynosphinxes they hold a twisted mix of a lust and hate, simultaneously envying their beauty and power while craving them as mates. Hieracosphinxes attack other sphinxes whenever they have them at a disadvantage. Male sphinxes of other species they tear to shreds or drive away, whereas they prefer to leave gynosphinxes ravaged but alive. The other species of sphinx likewise hold nothing but disdain for hieracosphinxes, and typically attack these vile beasts on sight.\n\nHieracosphinxes guard their territory ruthlessly against weaker intruders, seldom giving warning before they attack. They have no use for banter and riddles, making most efforts at diplomacy rather ineffective, but can be convinced to call off their attacks by convincing shows of force coupled with information on the location of weaker prey or a gynosphinx. Though poor fliers, they still prefer to fight from the air, the better to escape if the combat turns against them.\n\nAs they lack the ego and resourcefulness of the rest of their breed, hieracosphinxes can be pressed into service of mounts, particularly by those of similarly evil dispositions. Hieracosphinxes chafe under such service but submit to more powerful riders, though they still inf lict their foul tempers on any weaker creatures that happen by. A grown hieracosphinx can easily consume a full horse's worth of meat in a day, making their upkeep rather expensive. Even with these drawbacks, hieracosphinx eggs command values of up to 1,500 gp on the open market, as do young hieracosphinxes. It takes 3 years for a hieracosphinx to reach maturity, after which an untrained hieracosphinx only rarely accepts a rider without magical compulsion. Trainers, though hard to come by, charge thousands of gold pieces to rear and train a hieracosphinx, owing to the risk to life and limb.\n\nA light load for a hieracosphinx is up to 350 pounds; a medium load, 351-700 pounds; and a heavy load, 701-1,050 pounds. A typical hieracosphinx is just short of 9 ft. long and weighs 600 pounds. Hieracosphinxes detest bearing a rider into battle, thus increasing the DCs of any combat-related Ride checks by +5.","ecology":"","habitat_society":""},{"name":"Hippopotamus","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"animal","init":4,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+8 natural, -1 size","hp":59,"hd":"7d8+28","hdvalue":7,"fort":8,"ref":5,"will":3,"save_mods":"Fort: +10 vs. nonmagical disease","defensive_abilities":["sweat"],"speed":[{"type":"land","speed":40}],"melee":"bite +8 (2d8+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"capsize"},{"type":"trample","details":"1d8+6, DC 17"}],"strength":19,"dexterity":10,"constitution":16,"intelligence":2,"wisdom":13,"charisma":5,"baseatk":5,"cmb":9,"cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Endurance"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":8},{"skill":"Stealth","value":1,"special":"+11 underwater"},{"skill":"Swim","value":11}],"sq":[{"type":"hold breath"}],"environments":["warm rivers"],"organizations":["solitary","pair","bloat (3-20)"],"treasure":"none","description_visual":"This lumbering bull hippopotamus lunges out of the water and yawns wide, displaying an impressive set of tusk-like teeth.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Capsize","kind":"Ex","details":"A hippopotamus can overturn a boat of its size or smaller by ramming it as a charge attack and making a CMB check. The DC of this check is 25 or the result of the boat captain's Profession (sailor) check, whichever is higher."},{"type":"Sweat","kind":"Ex","details":"A hippo's reddish sweat protects it from nonlethal damage from hot environments, and grants it a +2 racial bonus on saving throws against nonmagical disease."}],"description":"The ill-tempered \"river horse\" has a well-earned reputation for hostility, despite the fact that it is a herbivore.","ecology":"","habitat_society":""},{"name":"Hypnalis","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"outsider","subtypes":["extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":59,"hd":"7d10+21","hdvalue":7,"fort":5,"ref":7,"will":6,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +13 (1d6+9 plus grab and poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d6+9"},{"type":"poison"},{"type":"sneak attack","details":"+2d6"}],"strength":22,"dexterity":15,"constitution":16,"intelligence":7,"wisdom":13,"charisma":10,"baseatk":7,"cmb":13,"cmb_special":"+4 vs. grapple","cmd":25,"cmd_special":"can't be tripped","feats":[{"feat":"Blind-Fight"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Stealth)"},{"feat":"Shadow Strike"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Fly","value":10},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":15}],"languages":["Aklo"],"sq":[{"type":"ghost touch fangs"},{"type":"phasing"}],"environments":["any (Ethereal Plane)"],"organizations":["solitary","pair","nest (3-7)"],"treasure":"none","description_visual":"Seeming to phase in and out of existence, this ophidian creature has a great striped hood like a cobra.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Ghost Touch Fangs","kind":"Su","details":"A hypnalis's bite attack is treated as if it has the ghost touch special weapon quality."},{"type":"Phasing","kind":"Su","details":"A hypnalis can shift from the Ethereal Plane to the Material Plane as a free action and shift back again as a move action (or part of a move action). The ability is otherwise identical to ethereal jaunt (CL 15th)."},{"type":"Poison","kind":"Su","details":"If a hypnalis poisons an ethereal creature while on the Ethereal Plane (including creatures under the effects of spells or effects that grant etherealness such as ethereal jaunt), the creature is immediately forced onto the Material Plane and takes the specified Constitution damage. Creatures on the Material Plane are affected by this poison as normal. Hypnalis Venom: Bite-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d3 Con and effects listed above; cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"Sometimes called an ether serpent, a hypnalis resembles a snake the size of a python sporting a hood like that of a cobra with gray stripes. The creature's fangs carry a potent venom that isn't only deadly, but can force creatures off the Ethereal Plane. While other denizens of the Ethereal Plane focus their attention on warring with each other, spying on others, or feeding on dreams, a hypnalis hunts those not native to its plane. Different hypnalises deal with such interlopers in their own ways. Some sinister or young and hotheaded hypnalises hunt such trespassers for sport, tormenting them for a while before killing them or expelling them to the Material Plane. Other older or inquisitive hypnalises are more curious about such strangers and pragmatic in their dealings with them, approaching interlopers in attempts to find out their method for traveling to the Ethereal Plane and whether or not they can return. If they can, these hypnalises might request that these interlopers leave, backing such requests with threats if the interlopers seem uncooperative. If the interlopers don't have a method to return to their home, some rare good-natured hypnalises may help them find a way to leave the Ethereal Plane without using its poison. Even when this is the case, hypnalises are wary creatures, and are always on guard against treachery. A hypnalis is approximately 8 ft. long and weighs about 20 pounds.","ecology":"","habitat_society":""},{"name":"Ice Golem","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"construct","subtypes":["cold"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"-1 Dex, +8 natural","hp":53,"hd":"6d10+20","hdvalue":6,"fort":2,"ref":1,"will":2,"dr":"5/adamantine","immunities":["construct traits","cold","magic"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +9 (1d6+3 plus 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"20-ft. cone, 3d6 cold damage, Reflex DC 13 half, usable once every 1d4 rounds"},{"type":"cold","details":"1d6"},{"type":"icy destruction"}],"strength":16,"dexterity":9,"wisdom":11,"charisma":1,"baseatk":6,"cmb":9,"cmd":18,"environments":["any cold"],"organizations":["solitary","gang (2-4)"],"treasure":"none","description_visual":"This icy statue stands a head taller than a normal human. A rime of frost coats it, and razor-sharp shards of ice adorn its limbs.","group":"Golem","source":"PFRPG Bestiary","special_abilities":[{"type":"Cold","kind":"Ex","details":"An ice golem's body generates intense cold, dealing 1d6 points of damage with its touch. Creatures attacking an ice golem with unarmed strikes or natural weapons take this same cold damage each time one of their attacks hits."},{"type":"Icy Destruction","kind":"Ex","details":"When reduced to 0 hit points, an ice golem shatters in an explosion of jagged shards of ice. All creatures within a 10-foot burst take 3d6 points of slashing damage and 2d6 points of cold damage; a DC 13 Reflex save halves the damage. The save DC is Constitution-based."},{"type":"Immunity to Magic","kind":"Ex","details":"An ice golem is immune to any spell or spell-like ability that allows spell resistance, with the exception of spells and spell-like abilities that have the Fire descriptor, which affect it normally. In addition, certain spells and effects function differently against the creature, as noted below. • A magical attack that deals electricity damage slows an ice golem (as the slow spell) for 2d6 rounds, with no saving throw. • A magical attack that deals cold damage breaks any slow effect on the golem and heals 1 point of damage for every 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. An ice golem gets no saving throw against cold effects."}],"description":"Ice golems are humanoid automatons formed of carved ice. Their appearance can range from roughly chiseled figures of ice and snow to elaborately detailed ice sculptures and beautiful crystalline statues. Ice golems cannot speak, and move with the sound of cracking and popping ice. An ice golem stands 7 ft. tall and weighs 500 pounds. Construction An ice golem's body must be constructed from a single block of ice weighing at least 1,000 pounds. The ice is treated with magical powders and unguents worth at least 500 gp. Ice Golem CL 12th; Price 18,500 gp Construction Requirements Craft Construct, chill touch, cone of cold, geas/ quest, ice storm, resist energy (cold), creator must be caster level 12th; Skill Craft (sculptures) DC 17; Cost 9,500 gp","ecology":"","habitat_society":""},{"name":"Ja Noi","cr":5,"xp":1600,"alignment":"LE","size":"Medium","type":"outsider","subtypes":["goblinoid","native","oni","shapechanger"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 armor, +2 Dex, +4 natural","hp":57,"hd":"6d10+24","hdvalue":6,"hp_mods":["regeneration 3 (acid or fire)"],"fort":9,"ref":7,"will":3,"speed":[{"type":"land","speed":30}],"melee":"mwk tetsubo +11 (1d10+6/4)","ranged":"longbow +8 (1d8/3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"bull's strength"}]},{"frequency":"3/day","spells":[{"spell":"command"},{"spell":"doom"},{"spell":"fly"},{"spell":"magic weapon"}]}],"strength":19,"dexterity":15,"constitution":18,"intelligence":12,"wisdom":13,"charisma":14,"baseatk":6,"cmb":10,"cmd":22,"feats":[{"feat":"Cleave"},{"feat":"Outflank"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":11},{"skill":"Disguise","value":11},{"skill":"Fly","value":11},{"skill":"Intimidate","value":11},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":11}],"languages":["Common","Goblin"],"sq":[{"type":"change shape","details":"Small or Medium humanoid, alter self"},{"type":"serene fighter"}],"environments":["temperate hills","warm hills"],"organizations":["solitary","patrol (2-4)","warband (5-7 plus 8-15 hobgoblins)","company (8-12 plus 20-50 hobgoblins, 1-2 lieutenants of 4th-5th level, and 1 general of 7th- 10th level)"],"treasure":"standard","description_visual":"This hunchbacked, fiery-skinned humanoid possesses black eyes beneath the bony ridges of its brow, wears elaborate heavy armor, and wields an ornate metal club.","group":"Oni","source":"AP 52","special_abilities":[{"type":"Serene Fighter","kind":"Su","details":"A ja noi is extremely disciplined and maintains its focus even in the midst of combat. Once per day as an immediate action, a ja noi may reroll a Will save."}],"description":"A ja noi is an oni spirit that takes the form of a hobgoblin, and differs physically from the hobgoblins in a variety of ways, most notably its unearthly strength and distorted appearance. A ja noi's skin blazes a fiery red rather than a drab gray, and the oni bears prominent ridges on its brow and forehead.\n\nJa noi live to fight. While not as physically powerful as most oni, ja noi nonetheless have an insatiable thirst for combat that drives them to pursue the trials of battle\n\nand bloodshed. The sensation of hot blood splattering on a ja noi's skin provokes an adrenaline rush that only fuels its lust for the kill. Its broad, tightly muscled physique and prowess in combat inspire awe within typical hobgoblins, who see the ja noi as a leader who ensures victory in their conquests.\n\nTowering over the hobgoblins it resembles, a ja noi stands a little over 6 ft. tall and weighs about 220 pounds.\n\nEcology\n\nAll oni believe the Material Plane's inhabitants fail to take advantage of the wealth of sensations they have at their disposal. While most of these evil spirits inhabit shells and rise to power by working behind the scenes- manipulating others into doing most of their foul deeds for them-ja noi take a more direct approach, conquering and slaughtering any who would stand against them and their armies. Ja noi embrace the carnal joys of slaughter, and no situation is more pleasant to a ja noi than the heat of combat upon a war-ravaged battlef ield. These hardened oni often recognize the inevitable outcome of their warlike tendencies, knowing that death could always be just around the corner; this knowledge, however, only further stimulates their greed for sensation, inspiring them to embrace every fight, as they know it could be their last. A ja noi silences its mind and ignores everything else while on the battlef ield, reveling in the current moment and the sensations of combat: the crunch of bones beneath a worn club, the spray of dying foes' blood, and the scattered guts and heads of fallen brawlers.\n\nLike other oni, ja noi possess the ability to change shape, and often use this ability to confuse enemies in the midst of battle, altering their appearances to look like allies, only to bash in an unsuspecting foe's head before the victim knows what's happened. This brutish trickery is usually the extent of a ja noi's guile, however, as the hobgoblin oni are hardly known for their cunning. Even in regard to tactics, ja noi usually implement only the basest plans of action, simply relying on their weaker minions to take the brunt of an opposing army's blow while they target the commanders, always seeking the most worthy challenger and forever striving for that feeling that comes just as one is fighting for one's life. The most powerful ja noi are exceptions to this rule, however, and tales tell of expert ja noi leaders who excel in both physical prowess and tactical wit. These commanders quickly reach the status of generals, and work alongside other oni to manipulate vast armies of soldiers, both humanoid and goblinoid.\n\nOnce they take physical form, ja noi rarely last more than a couple years on the Material Plane, their deadly lifestyle often a limiting factor in this regard. They either\n\ndie in battle or at the hands of mutinous troops or allies, minions who realize that they are merely pawns in the game of war that the ja noi is constantly playing. Thus, most of these oni practice their battle skills constantly against one another, their strongest hobgoblin followers, and their adroit adversaries, always fighting and becoming more powerful. While they care little for the arcane, ja noi hone some magical abilities in order to inf lict maximum damage on the battlefield, and a few even seek out magical items to bolster their strength.\n\nHabitat & Society\n\nWhereas many oni prefer to act alone and in secret, ja noi recognize the concept of strength in numbers, and understand that banding together is often a surer way to glorious victories than lone pursuits. The rare lone ja noi may seek out renowned heroes and martial senseis to challenge in one-on-one combat, but most of these creatures know the best way to demonstrate their prowess is in the midst of the chaotic battlefield in front of other oni, especially fellow ja noi. Often, when ja noi work together to bring carnage to the field of war, they keep track of each other's kills, ranking one another in terms of strength and skill. An individual who shows cowardice repeatedly or doesn't prove a useful ally swiftly meets the blade of a supposed comrade, as ja noi have little patience for weak accomplices.\n\nJa noi are seen as lowly and primal by other oni, but they possess immense amounts of authority among the lesser hobgoblins around them, and so they surround themselves with these minions, viewing them as useful fodder for the battles to come. During the fight, a ja noi's amateur hobgoblin warriors combat the masses of the opposing army, allowing the prideful oni to engage the commanders. Having found what they consider an ideal\n\nmilitaristic race, ja noi prefer to use hobgoblins for their war campaigns if possible, though they settle for other soldiers if doing so clearly benefits the oni and they have the mortals' unquestioning loyalty. More often, a ja noi will employ non-hobgoblin minions to serve as slaves or some other form of chattel, putting them to work crafting armor and weapons or cleaning up during the aftermath of a successful battle.\n\nIn rare cases, more powerful oni ask ja noi to lead armies against particularly stubborn groups of opponents. Ja noi rarely refuse such requests, knowing that much blood will be shed in the ventures-and that denying the requests of stronger oni is a sure path to a quick death. Like all oni, ja noi despise and seek out kami, reveling in the destruction of minor spirits and hunting the more powerful individuals for the sheer challenge of it. Because of the strictures of the Laws of Golden Perfection, ja noi cannot directly slay kami, and so they work to direct their vicious hobgoblin armies to complete the task instead.\n\nIn extremely rare cases, when they have no campaigns to wage and no humanoid enemies to battle, ja noi simply disappear into the wilderness to fight the mightiest creatures they can find. Laying waste to big game such as bulettes and owlbears can distract a ja noi between large-scale battles, but it doesn't take long before the natural warrior quickly feels the lust for battle surge within it once again. Given too much time between skirmishes, a ja noi might turn its violent attention toward its followers, slaughtering entire hobgoblin tribes out of frustration and madness. Canny hobgoblins in service to a bloodthirsty ja noi are wise to find opposing groups for the oni to battle, that the resulting conf lict might temporarily sate the ja noi's incessant desire for war.","ecology":"All oni believe the Material Plane's inhabitants fail to take advantage of the wealth of sensations they have at their disposal. While most of these evil spirits inhabit shells and rise to power by working behind the scenes- manipulating others into doing most of their foul deeds for them-ja noi take a more direct approach, conquering and slaughtering any who would stand against them and their armies. Ja noi embrace the carnal joys of slaughter, and no situation is more pleasant to a ja noi than the heat of combat upon a war-ravaged battlef ield. These hardened oni often recognize the inevitable outcome of their warlike tendencies, knowing that death could always be just around the corner; this knowledge, however, only further stimulates their greed for sensation, inspiring them to embrace every fight, as they know it could be their last. A ja noi silences its mind and ignores everything else while on the battlef ield, reveling in the current moment and the sensations of combat: the crunch of bones beneath a worn club, the spray of dying foes' blood, and the scattered guts and heads of fallen brawlers.\n\nLike other oni, ja noi possess the ability to change shape, and often use this ability to confuse enemies in the midst of battle, altering their appearances to look like allies, only to bash in an unsuspecting foe's head before the victim knows what's happened. This brutish trickery is usually the extent of a ja noi's guile, however, as the hobgoblin oni are hardly known for their cunning. Even in regard to tactics, ja noi usually implement only the basest plans of action, simply relying on their weaker minions to take the brunt of an opposing army's blow while they target the commanders, always seeking the most worthy challenger and forever striving for that feeling that comes just as one is fighting for one's life. The most powerful ja noi are exceptions to this rule, however, and tales tell of expert ja noi leaders who excel in both physical prowess and tactical wit. These commanders quickly reach the status of generals, and work alongside other oni to manipulate vast armies of soldiers, both humanoid and goblinoid.\n\nOnce they take physical form, ja noi rarely last more than a couple years on the Material Plane, their deadly lifestyle often a limiting factor in this regard. They either\n\ndie in battle or at the hands of mutinous troops or allies, minions who realize that they are merely pawns in the game of war that the ja noi is constantly playing. Thus, most of these oni practice their battle skills constantly against one another, their strongest hobgoblin followers, and their adroit adversaries, always fighting and becoming more powerful. While they care little for the arcane, ja noi hone some magical abilities in order to inf lict maximum damage on the battlefield, and a few even seek out magical items to bolster their strength.","habitat_society":"Whereas many oni prefer to act alone and in secret, ja noi recognize the concept of strength in numbers, and understand that banding together is often a surer way to glorious victories than lone pursuits. The rare lone ja noi may seek out renowned heroes and martial senseis to challenge in one-on-one combat, but most of these creatures know the best way to demonstrate their prowess is in the midst of the chaotic battlefield in front of other oni, especially fellow ja noi. Often, when ja noi work together to bring carnage to the field of war, they keep track of each other's kills, ranking one another in terms of strength and skill. An individual who shows cowardice repeatedly or doesn't prove a useful ally swiftly meets the blade of a supposed comrade, as ja noi have little patience for weak accomplices.\n\nJa noi are seen as lowly and primal by other oni, but they possess immense amounts of authority among the lesser hobgoblins around them, and so they surround themselves with these minions, viewing them as useful fodder for the battles to come. During the fight, a ja noi's amateur hobgoblin warriors combat the masses of the opposing army, allowing the prideful oni to engage the commanders. Having found what they consider an ideal\n\nmilitaristic race, ja noi prefer to use hobgoblins for their war campaigns if possible, though they settle for other soldiers if doing so clearly benefits the oni and they have the mortals' unquestioning loyalty. More often, a ja noi will employ non-hobgoblin minions to serve as slaves or some other form of chattel, putting them to work crafting armor and weapons or cleaning up during the aftermath of a successful battle.\n\nIn rare cases, more powerful oni ask ja noi to lead armies against particularly stubborn groups of opponents. Ja noi rarely refuse such requests, knowing that much blood will be shed in the ventures-and that denying the requests of stronger oni is a sure path to a quick death. Like all oni, ja noi despise and seek out kami, reveling in the destruction of minor spirits and hunting the more powerful individuals for the sheer challenge of it. Because of the strictures of the Laws of Golden Perfection, ja noi cannot directly slay kami, and so they work to direct their vicious hobgoblin armies to complete the task instead.\n\nIn extremely rare cases, when they have no campaigns to wage and no humanoid enemies to battle, ja noi simply disappear into the wilderness to fight the mightiest creatures they can find. Laying waste to big game such as bulettes and owlbears can distract a ja noi between large-scale battles, but it doesn't take long before the natural warrior quickly feels the lust for battle surge within it once again. Given too much time between skirmishes, a ja noi might turn its violent attention toward its followers, slaughtering entire hobgoblin tribes out of frustration and madness. Canny hobgoblins in service to a bloodthirsty ja noi are wise to find opposing groups for the oni to battle, that the resulting conf lict might temporarily sate the ja noi's incessant desire for war.","gear":"masterwork leather armor, masterwork tetsubo, longbow with 20 arrows"},{"name":"Killer Seahorse","cr":5,"xp":1600,"alignment":"N","size":"Huge","type":"animal","subtypes":["aquatic"],"init":1,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"+8 armor, +1 Dex, -2 size","hp":63,"hd":"6d8+36","hdvalue":6,"fort":10,"ref":6,"will":3,"defensive_abilities":["anchor (see giant seahorse)"],"speed":[{"type":"swim","speed":40}],"melee":"bite +10 (1d8+8 plus bleed), tail slap +5 (1d6+4 plus grab)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"constrict","details":"1d6+8"}],"strength":26,"dexterity":12,"constitution":21,"intelligence":1,"wisdom":12,"charisma":7,"baseatk":4,"cmb":14,"cmd":25,"feats":[{"feat":"Endurance"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":13},{"skill":"Swim","value":16}],"environments":["any oceans"],"organizations":["solitary","pair","school (3-8)"],"treasure":"none","description_visual":"This elephant-sized sea creature resembles a horse crossed with a fish, with crazed whirling eyes.","group":"Seahorse","source":"PFRPG Bestiary 4","description":"These specially bred offshoots of the giant seahorse are used by aquatic creatures as guard animals. Vicious and territorial, they prefer larger prey and have been known to eat giant crabs and careless handlers. Killer seahorses are too unruly for use as mounts and only accept riders or baggage if magically controlled. Killer seahorses have been known to crush other creatures into a bloody pulp just before giving birth, ensuring a good meal for their newborns (called \"fry\"). A killer seahorse fry is the size of a human hand and is an aggressive swarm feeder, like a piranha. A light load for a killer seahorse is up to 2,500 pounds, a medium load is 4,900 pounds, and a heavy load is 7,400 pounds. A killer seahorse can drag 36,800 pounds.","ecology":"","habitat_society":""},{"name":"Kodama","cr":5,"xp":1600,"alignment":"N","size":"Small","type":"outsider","subtypes":["kami","native"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+1 Dex, +2 dodge, +4 natural, +1 size","hp":51,"hd":"6d10+18","hdvalue":6,"hp_mods":["fast healing 3"],"fort":10,"ref":6,"will":4,"dr":"5/cold iron","immunities":["bleed","mind-affecting effects","petrification","polymorph"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":16,"speed":[{"type":"land","speed":30}],"melee":"2 claws +9 (1d3+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"distracting gaze"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"speak with plants","details":"trees only"},{"spell":"tree shape"}]},{"frequency":"3/day","spells":[{"spell":"charm animal"},{"spell":"entangle"},{"spell":"tree stride","details":"self plus 50 lbs. of objects only"}]}],"strength":14,"dexterity":13,"constitution":16,"intelligence":11,"wisdom":14,"charisma":17,"baseatk":6,"cmb":7,"cmd":20,"feats":[{"feat":"Great Fortitude"},{"feat":"Nimble Moves"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":11},{"skill":"Escape Artist","value":10},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":11},{"skill":"Stealth","value":14},{"skill":"Survival","value":11}],"languages":["Common","speak with plants","telepathy 100 ft."],"sq":[{"type":"merge with ward"},{"type":"ward","details":"wild trees"}],"environments":["any forests"],"organizations":["solitary","pair","group (3-7)","grove (8-16)"],"treasure":"standard","description_visual":"This little green humanoid figure stands only three ft. tall. Its head is faceless save for two hollow pits for eyes.","group":"Kami","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Distracting Gaze","kind":"Su","details":"Staggered for 1d4 rounds, 30 ft., Will DC 16 negates. This is a mind-affecting effect that requires the kodama to be visible to those it wishes to affect. The save DC is Charisma-based."}],"description":"Revered by druids and rangers for their attunement with the wilds, kodama, known also as tree kami, are the guardians of the wild trees of the forest-they don't protect trees cultivated and grown in civilized areas. (Those trees are protected by different kami, if at all.) A kodama takes a single tree under its protection; typically, all of the trees in a forest that are protected by kodama are clustered together in one particular area.\n\nA kodama in its physical form resembles a barely humanoid creature with only the vaguest of features on its semispherical head. A tree kami is 3 ft. tall and weighs 60 pounds. While one might expect the kami of something as large as a tree to itself be larger, the fact that forests are made up of so many trees tends to diminish the singular \"presence\" any single tree might have. In cases where a tree is particularly ancient or immense, however, the kodama associated with it is much larger-statistics for such rare kodama can be generated by advancing the kodama given here by several Hit Dice and increasing its size-theoretically, a Colossal kodama with more than 20 Hit Dice could exist somewhere in the world. Not all kodama increase in power by gaining racial Hit Dice, though, as some instead progress by gaining class levels, particularly levels of druid, though a rare few kodama kami-those possessed of minds more ordered and structured than is normal for their race-take the path of the monk.\n\nKodama are more curious about visitors than most kami, and often manifest their physical bodies simply to watch and observe newcomers to their groves. A kodama usually manifests on the far side of its tree, or in the shadows of the undergrowth, so that it can slowly step out into visibility to quietly observe with its distracting, empty-eyed gaze. This gaze can be particularly unnerving. Those who have fallen under its supernatural effects often have different descriptions of how the gaze made them feel (ashamed, frightened, curious, amused, and nervous being the most common reactions), yet the end result is essentially the same. While under observation by a curious kodama, few are those who can continue their actions without being at least somewhat distracted by the kami's attention.\n\nWhen a kodama must fight (typically in order to defend its tree or other kami), it moves quickly-kodama work best in groups, and when confronted alone generally use tree stride to travel to another part of the forest to raise a small host of allies to aid.","ecology":"","habitat_society":""},{"name":"Lampad","cr":5,"xp":1600,"alignment":"CN","size":"Medium","type":"fey","init":5,"senses":[{"type":"darkvision","modifier":"90 ft."},{"type":"low-light vision"}],"auras":["insane beauty (30 ft.)"],"ac":20,"ac_touch":20,"ac_flat_footed":15,"ac_mods":"+5 deflection, +5 Dex","hp":52,"hd":"7d6+28","hdvalue":7,"fort":6,"ref":10,"will":8,"dr":"5/cold iron","speed":[{"type":"land","speed":30}],"melee":"mwk dagger +9 (1d4/19-20)","ranged":"mwk sling +9 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weep"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"meld into stone"},{"spell":"stone tell"}]}],"spellsprepared_caster":"druid","spellsprepared_caster_level":5,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":3,"spell_slots":1,"spells":[{"spell":"stone shape"}]},{"spell_level":2,"spell_slots":1,"spells":[{"spell":"spider climb"},{"spell":"stone call"}]},{"spell_level":1,"spell_slots":1,"spells":[{"spell":"cure light wounds"},{"spell":"faerie fire"},{"spell":"magic stone"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"light"},{"spell":"mending"}]}],"strength":10,"dexterity":21,"constitution":18,"intelligence":14,"wisdom":17,"charisma":21,"baseatk":3,"cmb":3,"cmd":23,"feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Point-Blank Shot"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Diplomacy","value":13},{"skill":"Knowledge (dungeoneering)","value":9},{"skill":"Knowledge (nature)","value":12},{"skill":"Linguistics","value":3},{"skill":"Perception","value":15},{"skill":"Perform (sing)","value":9},{"skill":"Sense Motive","value":15},{"skill":"Spellcraft","value":9},{"skill":"Stealth","value":15},{"skill":"Use Magic Device","value":15}],"languages":["Aklo","Common","Undercommon"],"sq":[{"type":"guarded"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard (masterwork dagger, masterwork sling)","description_visual":"Tears stream from this beautiful but sullen creature's eyes, forming a puddle beneath her delicate ft.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Guarded","kind":"Su","details":"A lampad adds her Charisma modifier as a deflection bonus to her Armor Class."},{"type":"Insane Beauty","kind":"Su","details":"This ability affects all humanoids within 30 ft. who are viewing a lampad in conditions brighter than dim light. Those who look directly upon the lampad must succeed at a DC 18 Will save or gain the confused condition for 1d6 rounds. A creature that succeeds at the save is immune to the same lampad's insane beauty for 24 hours. A lampad can suppress or resume this ability as a free action. The save DC is Charisma-based. Spells A lampad casts spells as a 5th-level druid, but can't swap out prepared spells to cast summon spells."},{"type":"Weep","kind":"Su","details":"As a standard action, a lampad can unsettle those near her when she cries. Any creature within 30 ft. who can hear a lampad weeping becomes shaken unless it succeeds at a DC 18 Will saving throw. This ability can't cause a creature to become frightened or panicked. This is a mind-affecting fear effect that relies on audible components. The save DC is Charisma-based."}],"description":"Dark and moody cousins to nymphs, lampads sulk along natural caverns and dank tunnels, their weeping cries echoing through the darkness. These creatures are often found carrying light in caverns and dungeons, drawing creatures to them like moths to flame. Though they prefer the darkness, they know that exposing their forms under bright conditions gives them an edge over creatures viewing them. Just as nymphs guard nature's purest places and dryads protect their sacred trees, lampads watch over the dark places of the world. They speak to the stone that forms their murky world, and their forlorn cries ring out through the belly of the earth.","ecology":"","habitat_society":""},{"name":"Lar","cr":5,"xp":1600,"alignment":"LG","size":"Medium","type":"outsider","subtypes":["good","incorporeal","lawful","native"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":17,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+2 deflection, +3 Dex, +2 size","hp":39,"hd":"6d10+6","hdvalue":6,"hp_mods":["regeneration 1 (in statua)"],"fort":3,"ref":7,"will":4,"speed":[{"type":"land","speed":0},{"type":"fly","speed":30,"maneuverability":"perfect"}],"space":"2-1/2 ft.","reach":"0 ft.","special_attacks":[{"type":"suggestion"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"create water"},{"spell":"detect evil"},{"spell":"ghost sound"},{"spell":"guidance"},{"spell":"lullaby"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"},{"spell":"purify food and drink"}]},{"frequency":"1/day","spells":[{"spell":"calm emotions"},{"spell":"continual flame"},{"spell":"gust of wind"},{"spell":"pyrotechnics"},{"spell":"whispering wind"}]},{"frequency":"3/day","spells":[{"spell":"bless"},{"spell":"bless water"},{"spell":"dancing lights"},{"spell":"produce flame"},{"spell":"protection from evil"},{"spell":"sanctuary"},{"spell":"unseen servant"}]}],"strength":10,"dexterity":17,"constitution":13,"intelligence":12,"wisdom":15,"charisma":14,"baseatk":6,"cmb":6,"cmd":19,"feats":[{"feat":"Alertness"},{"feat":"Improved Lightning Reflexes"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Craft (any two)","value":10},{"skill":"Heal","value":11},{"skill":"Knowledge (local)","value":10},{"skill":"Knowledge (religion)","value":7},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13}],"languages":["telepathy 100 ft."],"sq":[{"type":"genius loci"},{"type":"naturally invisible"},{"type":"statua"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"A stirring in the air and rustle through the room reveals a presence-a subtle aura both cautious and curious.","source":"AP 27","special_abilities":[{"type":"Genius Loci","kind":"Su","details":"As a free action, a lar can possess any inanimate object with which it comes into contact, thereby animating it under its control. The object and lar merge, taking on the statistics of an animated object of the same size. A lar may possess any object of Tiny to Large size. If the animated object is destroyed or targeted by dispel good, the lar is expelled and takes 1d6 points of damage per size category of the possessed object-1d6 for a Tiny object, 2d6 for a Small object, and so on. The lar is then free to possess another object, if one is available. If a lar is reduced to 0 hit points or fewer, it is banished to its statua for 24 hours, after which it is fully healed. If the lar doesn't have a statua, or the statua is destroyed while it is at 0 or fewer hit points, the lar is killed."},{"type":"Natural Invisibility","kind":"Su","details":"This ability is constant, allowing a lar to remain invisible even when attacking. This ability is inherent and not subject to the invisibility purge spell."},{"type":"Statua","kind":"Su","details":"All lares rely on a small stone figure, known as a statua, for survival. This figurine serves as a lar's home, resting place, and tie to the Material Plane. Lares typically rest within their statua, finding it a comfortable place from which to oversee their surroundings. For every round a lar spends doing nothing besides resting within its statua, it regenerates 1 point of damage. However, being separated from the statua for extended periods of time weakens the lar. For every 5 hours a lar remains outside of its statua, it takes 1d6 points of nonlethal damage. Only returning to the statua can heal this damage. If a lar falls to 0 hit points, even from nonlethal damage, it is banished back to the Upper Planes. While a lar's statua exists, the connected lar is treated as a native outsider. Any attempt to banish the lar-through dismissal or a similar spell-merely transports the creature back to its statua. If the statua is destroyed, a lar can be dismissed from the Material Plane as normal."},{"type":"Suggestion","kind":"Sp","details":"A lar can influence creatures as per the spell suggestion, with some variations, at will. First, to influence a creature in this manner, a lar must occupy the same square as its target. The lar is considered to be able to speak any language and communicate with any creature-even animals and vermin (which are usually immune to mind-affecting effects)-for the purposes of this effect. The target may attempt to resist a lar's suggestion by making a DC 17 Will save. The save DC is Charisma-based and includes a +2 racial bonus."}],"description":"Sometimes referred to as \"watchsouls,\" lares are subtle, benevolent spirits that prefer to spend their existence on the Material Plane minding the homes and fortunes of deserving mortals. Kind but aloof, lares watch over their mortal wards and help only when they are most needed. Yet where their homes are intruded upon or their charges imperiled, they prove frighteningly effective guardians, turning everything in their tiny dominions into living weapons. Lares are innately invisible, making the nature of their existence something of a mystery. Originating from the Upper Planes, these spirits have no true bodies and appear only as vague spectral eddies to those capable of seeing invisible beings. Yet while their forms prove vague, their blessings are undeniable. Ecology Although formed upon the Upper Planes, lares find themselves drawn to the Material Plane. While some seek out mortal souls to watch over out of some innate sense of protectiveness, others feel a more specific draw, searching out members of specific races, nations, heritages, or families. Upon taking up residence in a home of their choosing, what motivates and sustains these benevolent spirits is little understood. They seem to take sustenance from positive emotions, growing weak if left in places with quarrelsome residents or that fall to ruin. Lares never seem to die from negative emotions or abandonment, though, merely biding their time in the hopes that their dwelling might someday again host amenable residents. Habitat & Society Mortals sharing their home with a lar often create household shrines to them. These tiny sanctuaries, called lararia (singular lararium), serve to house the lar's statuae. Though the lar doesn't require offerings, many families give them anyway, treating their spirit with reverence. Over time, the lar might become like a member of the family, with the spirit offering advice and taking a keen interest in the raising of children and protection of the home. Once a family has been chosen, a lar doesn't leave its dwelling, not even to follow the family during extended leaves. The only exception to this is if the family takes the statua with them, though this isn't a practice lares encourage. Since the statuae are their anchors to the Material Plane, lares are insecure about exposing them to the outside world where they might be lost, stolen, or damaged. Summoning a Lar A tradtion said to have been created and passed down since the days of lost Azlant, many families, homes, and even shops and public buildings along the Inner Sea invite lares to take up residence, seeking the blessings of the divine. Few, however, know when their invitations have been accepted, though, as a lar might prove aloof for months or years as it gauges its new wards. In order to welcome such spirits, families construct tiny effigies called statuae in the shapes of honored ancestors, regional heroes, or fanciful creatures, in which the spirits might come and reside. These statuae are non-magical effigies, typically composed of stone or fine wood and anointed with fine lacquers and oils, requiring 2 days, a successful DC 20 Craft check, and 40 gp to create. Once created, these Diminuative figures typically have a hardness of 5 and 10 hit points. If destroyed, a statua may be recreated in this same method. Summoning a lar is a more elaborate affair, requiring nightly prayers and small offerings of fruit, incense, flowers, and similar gifts to the statuae. For each night one prays to the figure for their home or family's protection there is a cumulative 1% chance a lar hears and turns its attention to the petitioner. This attention doesn't mean that a lar will aid a home, but merely that it has heard the prayer, and it might yet decide that its philosophies and virtues are incompatible with the supplicant. If such is the case, the lar quietly ignores the prayer, and the petitioner's chance to gain a lar's attention resets to 0%, all entirely unknown to the mortal. When a lar does accept an invitation, it may immediately plane shift to the associated statua, claiming it as its own. A lar typically makes some subtle acknowledgement that it has come, perhaps slightly altering its statua's appearance or lighting candles upon its arrival. It still often takes months, even years, for a lar to become intimate with a family and make its presence actively known, and some never do. Lares in Golarion Lares exhibit extremely variable personalities, and while some prove aloof even after centuries, others become gregarious members of their protected families. Noted here are just two such dichotomous lares rumored to guard sites in Golarion. Uncle Penates: When only the members of the Aphinius family of Taldor are present, their home's lar possesses the expensive painting within their drawing room. From its hidden statua just behind the painting, the boisterous spirit delights in animating the fine oils to make it appear as though the paunchy and opulently dressed Taldan nobleman pictured is personally relaxing and conversing with the family members nearby. None of the family know the nature of the effect, many believing the house is haunted by the spirit of their ancestor, but none fear or begrudge the presence of kind old Uncle Penates. Wolz: This lar has long lingered in the burnt-out ruin of an old stone cottage just east of Windsong Abby in Varisia. His wolf shaped statua having fallen beneath a pile of hearth stones, Wolz subtly watches over any goodly travelers who come to rest in the tiny ruin, lighting a fire, providing water, and warding off danger as if they were his long-lost family.","ecology":"Although formed upon the Upper Planes, lares find themselves drawn to the Material Plane. While some seek out mortal souls to watch over out of some innate sense of protectiveness, others feel a more specific draw, searching out members of specific races, nations, heritages, or families. Upon taking up residence in a home of their choosing, what motivates and sustains these benevolent spirits is little understood. They seem to take sustenance from positive emotions, growing weak if left in places with quarrelsome residents or that fall to ruin. Lares never seem to die from negative emotions or abandonment, though, merely biding their time in the hopes that their dwelling might someday again host amenable residents.","habitat_society":"Mortals sharing their home with a lar often create household shrines to them. These tiny sanctuaries, called lararia (singular lararium), serve to house the lar's statuae. Though the lar doesn't require offerings, many families give them anyway, treating their spirit with reverence. Over time, the lar might become like a member of the family, with the spirit offering advice and taking a keen interest in the raising of children and protection of the home. Once a family has been chosen, a lar doesn't leave its dwelling, not even to follow the family during extended leaves. The only exception to this is if the family takes the statua with them, though this isn't a practice lares encourage. Since the statuae are their anchors to the Material Plane, lares are insecure about exposing them to the outside world where they might be lost, stolen, or damaged. Summoning a Lar A tradtion said to have been created and passed down since the days of lost Azlant, many families, homes, and even shops and public buildings along the Inner Sea invite lares to take up residence, seeking the blessings of the divine. Few, however, know when their invitations have been accepted, though, as a lar might prove aloof for months or years as it gauges its new wards. In order to welcome such spirits, families construct tiny effigies called statuae in the shapes of honored ancestors, regional heroes, or fanciful creatures, in which the spirits might come and reside. These statuae are non-magical effigies, typically composed of stone or fine wood and anointed with fine lacquers and oils, requiring 2 days, a successful DC 20 Craft check, and 40 gp to create. Once created, these Diminuative figures typically have a hardness of 5 and 10 hit points. If destroyed, a statua may be recreated in this same method. Summoning a lar is a more elaborate affair, requiring nightly prayers and small offerings of fruit, incense, flowers, and similar gifts to the statuae. For each night one prays to the figure for their home or family's protection there is a cumulative 1% chance a lar hears and turns its attention to the petitioner. This attention doesn't mean that a lar will aid a home, but merely that it has heard the prayer, and it might yet decide that its philosophies and virtues are incompatible with the supplicant. If such is the case, the lar quietly ignores the prayer, and the petitioner's chance to gain a lar's attention resets to 0%, all entirely unknown to the mortal. When a lar does accept an invitation, it may immediately plane shift to the associated statua, claiming it as its own. A lar typically makes some subtle acknowledgement that it has come, perhaps slightly altering its statua's appearance or lighting candles upon its arrival. It still often takes months, even years, for a lar to become intimate with a family and make its presence actively known, and some never do. Lares in Golarion Lares exhibit extremely variable personalities, and while some prove aloof even after centuries, others become gregarious members of their protected families. Noted here are just two such dichotomous lares rumored to guard sites in Golarion. Uncle Penates: When only the members of the Aphinius family of Taldor are present, their home's lar possesses the expensive painting within their drawing room. From its hidden statua just behind the painting, the boisterous spirit delights in animating the fine oils to make it appear as though the paunchy and opulently dressed Taldan nobleman pictured is personally relaxing and conversing with the family members nearby. None of the family know the nature of the effect, many believing the house is haunted by the spirit of their ancestor, but none fear or begrudge the presence of kind old Uncle Penates. Wolz: This lar has long lingered in the burnt-out ruin of an old stone cottage just east of Windsong Abby in Varisia. His wolf shaped statua having fallen beneath a pile of hearth stones, Wolz subtly watches over any goodly travelers who come to rest in the tiny ruin, lighting a fire, providing water, and warding off danger as if they were his long-lost family."},{"name":"Large Air Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":11,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":17,"ac_flat_footed":13,"ac_mods":"+7 Dex, +1 dodge, +4 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":9,"ref":13,"will":2,"defensive_abilities":["air mastery"],"dr":"5/-","immunities":["elemental traits"],"speed":[{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"2 slams +14 (1d8+4)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"whirlwind","details":"DC 18"}],"strength":18,"dexterity":25,"constitution":16,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":13,"cmd":31,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Mobility"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Escape Artist","value":15},{"skill":"Fly","value":21},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":11},{"skill":"Stealth","value":11}],"languages":["Auran"],"environments":["any (Plane of Air)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This cloud-like creature has dark hollows reminiscent of eyes and a mouth, and a howling wind whips it into ominous shapes.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Air Mastery","kind":"Ex","details":"Airborne creatures take a -1 penalty on attack and damage rolls against an air elemental."}],"description":"Air elementals are fast, flying creatures made of living air. Primitive and territorial, they resent being summoned or doing the bidding of mortals, and much prefer to spend their time on the Plane of Air, swooping and racing through the endless skies. Although all air elementals of a similar size have identical statistics, the exact appearance of an air elemental can vary wildly between individuals. One might be an animated vortex of wind and smoke, while another might be a smoky bird-like creature with glowing eyes and wind for wings. An air elemental prefers to attack flying or otherwise airbone targets, not only because its mastery over flight gives it a slight advantage, but also because it detests the thought of having to touch the ground. An air elemental can move underwater, and although it is an elemental and thus runs no risk of drowning, it has no ranks in Swim and loses much of its speed and mobility when underwater. Whirlwind Whirlwind Elemental Height Weight Save DC Height Small 4 ft. 1 lb. 12 10-20 ft. Medium 8 ft. 2 lbs. 14 10-30 ft. Large 16 ft. 4 lbs. 18 10-40 ft. Huge 32 ft. 8 lbs. 22 10-50 ft. Greater 36 ft. 10 lbs. 23 10-60 ft. Elder 40 ft. 12 lbs. 27 10-60 ft.","ecology":"","habitat_society":""},{"name":"Large Earth Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"-1 Dex, +10 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":9,"ref":1,"will":6,"dr":"5/-","immunities":["elemental traits"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20}],"speed_mod":"earth glide","melee":"2 slams +14 (2d6+7)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"earth mastery"}],"strength":24,"dexterity":8,"constitution":17,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":16,"cmd":25,"feats":[{"feat":"Cleave"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush","type":"bonus"},{"feat":"Improved Overrun"},{"feat":"Power Attack"}],"skills":[{"skill":"Appraise","value":6},{"skill":"Climb","value":15},{"skill":"Knowledge (dungeoneering)","value":3},{"skill":"Knowledge (planes)","value":6},{"skill":"Perception","value":11},{"skill":"Stealth","value":5}],"languages":["Terran"],"environments":["any (Plane of Earth)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This hulking, roughly humanoid creature of dirt and stone explodes up from the earth, faceless save for two glowing gemstone eyes.","group":"Elemental","source":"PFRPG Bestiary","special_abilities":[{"type":"Earth Glide","kind":"Ex","details":"A burrowing earth elemental can pass through stone, dirt, or almost any other sort of earth except metal as easily as a fish swims through water. If protected against fire damage, it can even glide through lava. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A move earth spell cast on an area containing a burrowing earth elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Earth Mastery","kind":"Ex","details":"An earth elemental gains a +1 bonus on attack and damage rolls if both it and its foe are touching the ground. If an opponent is airborne or waterborne, the elemental takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the elemental is initiating or resisting these kinds of attacks. (These modifiers are not included in the statistics block.)"}],"description":"Earth elementals are plodding, stubborn creatures made of living stone or earth. When utterly still, they resemble a heap of stone or a small hill. When an earth elemental lumbers into action, its actual appearance can vary, although its statistics remain identical to other elementals of its size. Most earth elementals look like terrestrial animals made out of rock, earth, or even crystal, with glowing gemstones for eyes. Larger earth elementals often have a stony humanoid appearance. Bits of vegetation frequently grow in the soil that makes up parts of an earth elemental's body. Elemental Height Weight Small 4 ft. 80 lbs. Medium 8 ft. 750 lbs. Large 16 ft. 6,000 lbs. Huge 32 ft. 48,000 lbs. Greater 36 ft. 54,000 lbs. Elder 40 ft. 60,000 lbs.","ecology":"","habitat_society":""},{"name":"Large Fire Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["elemental","extraplanar","fire"],"init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+5 Dex, +1 dodge, +4 natural, -1 size","hp":60,"hd":"8d10+16","hdvalue":8,"fort":8,"ref":11,"will":4,"dr":"5/-","immunities":["elemental traits","fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":50}],"melee":"2 slams +12 (1d8+2 plus burn)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"burn","details":"1d8, DC 16"}],"strength":14,"dexterity":21,"constitution":14,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":11,"cmd":27,"feats":[{"feat":"Dodge"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Climb","value":9},{"skill":"Escape Artist","value":12},{"skill":"Intimidate","value":9},{"skill":"Knowledge (planes)","value":5},{"skill":"Perception","value":11}],"languages":["Ignan"],"environments":["any (Plane of Fire)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This creature looks like a living, mobile bonfire, tongues of flame reaching out in search of things to burn.","group":"Elemental","source":"PFRPG Bestiary","description":"Fire elementals are quick, cruel creatures of living flame. They enjoy frightening beings weaker than themselves, and terrorizing any creature they can set on fire. A fire elemental cannot enter water or any other nonf lammable liquid. A body of water is an impassible barrier unless the fire elemental can step or jump over it or the water is covered with a flammable material (such as a layer of oil). Fire elementals vary in appearance-they usually manifest as coiling serpentine forms made of smoke and lame, but some fire elementals take on shapes more akin to humans, demons, or other monsters in order to increase the terror of their sudden appearance. Features on a fire elemental's body are made by darker bits of flame or patches of semi-stable smoke, ash, and cinders. Elemental Height Weight Small 4 ft. 1 lb. Medium 8 ft. 2 lbs. Large 16 ft. 4 lbs. Huge 32 ft. 8 lbs. Greater 36 ft. 10 lbs. Elder 40 ft. 12 lbs.","ecology":"","habitat_society":""},{"name":"Large Ice Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["air","cold","elemental","extraplanar","water"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"snow vision"}],"ac":17,"ac_touch":10,"ac_flat_footed":16,"ac_mods":"+1 Dex, +7 natural, -1 size","hp":68,"hd":"8d10+24","hdvalue":8,"fort":9,"ref":7,"will":2,"dr":"5/-","immunities":["cold","elemental traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20,"special":"ice and snow only"},{"type":"swim","speed":60}],"melee":"2 slams +12 (1d8+5 plus 1d6 cold)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"numbing cold","details":"DC 17"}],"strength":20,"dexterity":12,"constitution":17,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":14,"cmd":25,"cmd_special":"can't be tripped","feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Intimidate","value":11},{"skill":"Knowledge (planes)","value":9},{"skill":"Perception","value":11},{"skill":"Stealth","value":8},{"skill":"Swim","value":13}],"languages":["Aquan"],"sq":[{"type":"ice glide"},{"type":"icewalking"}],"environments":["any land (Plane of Water)","any water (Plane of Water)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"From the waist up, this icy creature's features are humanoid, but below its body is a snake-like, slithering tail.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Ice Glide","kind":"Su","details":"A burrowing ice elemental can pass through nonmagical ice and snow as easily as a fish swims through water. Its burrowing leaves behind no tunnel or hole, nor does it create any ripple or other sign of its presence. A control water spell cast on an area containing a burrowing ice elemental flings the elemental back 30 ft., stunning the creature for 1 round unless it succeeds on a DC 15 Fortitude save."},{"type":"Icewalking","kind":"Ex","details":"This ability works like the spider climb spell, but the surfaces the elemental climbs must be icy. The elemental can move across icy surfaces without penalty and doesn't need to make Acrobatics checks to run or charge on ice."},{"type":"Numbing Cold","kind":"Su","details":"When an ice elemental deals cold damage to a creature, that creature must succeed on a Fortitude save or be staggered for 1 round. The save DC is listed in the elemental's stat block and is Constitution-based."},{"type":"Snow Vision","kind":"Ex","details":"An ice elemental can see perfectly well in snowy conditions and doesn't take any penalties on Perception checks while in snow."}],"description":"Ice elementals are creatures made of animated snow and ice. They form in especially cold parts of the Plane of Water and along its border with the Plane of Air, where giant icebergs careen off of world-high waterfalls into the open sky. Ice elementals vary in their exact appearance.","ecology":"","habitat_society":""},{"name":"Large Lightning Elemental","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"outsider","subtypes":["air","elemental","extraplanar"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":16,"ac_flat_footed":11,"ac_mods":"+6 Dex, +1 dodge, +2 natural, -1 size","hp":60,"hd":"8d10+16","hdvalue":8,"fort":8,"ref":12,"will":2,"dr":"5/-","immunities":["electricity","elemental traits"],"speed":[{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"2 slams +13 (1d8+3 plus 1d6 electricity)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"metal mastery"},{"type":"spark leap"}],"strength":16,"dexterity":23,"constitution":14,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":8,"cmb":12,"cmd":29,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":17},{"skill":"Escape Artist","value":17},{"skill":"Fly","value":12},{"skill":"Knowledge (planes)","value":9},{"skill":"Perception","value":11}],"languages":["Auran"],"environments":["any (Plane of Air)"],"organizations":["solitary","pair","gang (3-8)"],"treasure":"none","description_visual":"This creature looks like a dark storm cloud, with sparks suggesting eyes and long sweeping arms charged with bolts of lightning.","group":"Elemental","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Metal Mastery","kind":"Ex","details":"A lightning elemental gains a +3 bonus on attack rolls if its opponent is wearing metal armor, is wielding a metal weapon, or is made of metal (such as an iron golem)."},{"type":"Spark Leap","kind":"Ex","details":"A lightning elemental gains a +10 bonus on bull rush, disarm, overrun, and trip attacks when it charges a creature against whom its metal mastery ability applies."}],"description":"Though most think of the Plane of Air as a vast expanse of clear sky, that plane also holds the power of the storm, including monstrous hurricanes larger than entire worlds and thunderstorms whose peals and claps can shatter stone. Whether lightning elementals are the byproduct of common air elementals spending too much time near these electrically charged storms or are merely calved off like forgotten flurries, they are aggressive and almost suicidal in their willingness to leap into battle. They particularly enjoy attacking creatures that are made of metal and creatures that wear metal armor or wield metal weapons. Many lightning elementals have a roughly humanoid shape, but some prefer animalistic shapes (particularly birds and dragons), and a few appear to be nothing more than large disembodied heads made of dark clouds with flickering lightning tongues. Regardless of the shape a lightning elemental takes, the air around the creature hums and throbs with the promise of electrocution and the tangy stink of ozone.","ecology":"","habitat_society":""}];
